using namespace stalthos;using namespace stalthos::domain;
void check(bool b,const char*m){if(!b)throw std::runtime_error(m);}
int main(){try{
check(playableSpecies("Smalltrotter")==HeroSpecies::Smalltrotter && playableSpecies("Thistletail")==HeroSpecies::Thistletail,"implemented selection");for(const auto* name:{"Longstride","Reedcrest","Brackenback","","thistletail"}){bool denied=false;try{playableSpecies(name);}catch(const std::invalid_argument&){denied=true;}check(denied,"unimplemented choice accepted");}
MicroforagePatch p;check(p.sensed({p.x+12,2,p.z},2,1),"notice boundary");check(!p.sensed({p.x+12.001,2,p.z},2,1)&&!p.sensed({p.x,15,p.z},2,1)&&!p.sensed({p.x,2,p.z},2,0),"remote/vertical/depleted sensed");check(p.eligible({p.x,2,p.z},2,true,true)&&!p.eligible({p.x,2,p.z},2,false,true)&&!p.eligible({p.x,2,p.z},2,true,false)&&!p.eligible({p.x+1,2,p.z},2,true,true)&&!p.eligible({p.x,2.5,p.z},2,true,true),"body support/alive/reach gates");
needs::NeedsCore needs(HeroSpecies::Thistletail);needs.restoreState(.8,0,0,0,false);HeroSim hero;HeroDrinkAutonomy autonomy;Vec3 remote{p.x+36,2,p.z},near{p.x-6,2,p.z},food{p.x,2,p.z};auto action=autonomy.update(hero,needs,remote,0,.1,false,p.sensed(remote,2,1)?std::optional<Vec3>{food}:std::nullopt,false,false,needs::SuggestedActivity::Eat,p.resource);check(!hero.perception.attention()&&!action.active,"remote body gained food awareness");action=autonomy.update(hero,needs,near,1.57079632679,.1,false,food,true,false,needs::SuggestedActivity::Eat,p.resource);check(action.forward&&action.active&&hero.perception.attention()->source==p.resource,"local forage not normal intention");action=autonomy.update(hero,needs,near,0,.1,true,food,true,false,needs::SuggestedActivity::Eat,p.resource);check(!action.active&&!action.forward,"direct did not override");
ResourceLedger ledger;auto remaining=[&](Identity id){for(const auto&r:ledger.snapshot())if(r.id==id)return r.initialQuantity-r.consumedQuantity;throw std::runtime_error("missing resource");};check(ledger.load({{p.resource,ResourceKind::Shrub,1,0}}),"patch ledger load");InteractionsCore contacts;contacts.beginSession(13);double dummy=1;check(ledger.tryConsume(13,p.resource,.5)==ResourceAdmission::NewKey,"first exact finite consume");if(contacts.applyContact(13,p.resource,true,.5,dummy))needs.feed(.5);check(std::abs(needs.hunger()-.3)<1e-9&&p.fraction(remaining(p.resource))==.5,"exact relief/depletion");check(ledger.tryConsume(13,p.resource,.5)==ResourceAdmission::Replay&&!contacts.applyContact(13,p.resource,true,.5,dummy),"repeat replay consumed");contacts.beginSession(14);dummy=.5;check(ledger.tryConsume(14,p.resource,.5)==ResourceAdmission::NewKey&&contacts.applyContact(14,p.resource,true,.5,dummy),"second finite contact");check(remaining(p.resource)==0&&p.fraction(remaining(p.resource))==0&&!p.sensed(food,2,0),"exhausted patch still affords food");
std::vector<fauna::HabitatSite> sites{{{0,2,0},true,false,{1}},{{2,2,0},false,true,{0}}};ResourceLedgerDto fullHistory{{{100,ResourceKind::Creek,10,2},{200,ResourceKind::Shrub,10,1},{210,ResourceKind::Shrub,1,0}},{{90,100,2},{91,200,1}}};uint64_t allocator=100;engine::NativePopulationRegistry authoritative(fauna::Population(42,1001,sites,8),fullHistory,{},{{0,200,sites[0].position},{1,100,sites[1].position}},allocator);const auto npcBefore=authoritative.snapshot();check(authoritative.consume(13,210,.5),"native ledger denies food contact");check(!authoritative.consume(13,210,.5),"native ledger repeats contact");const auto nativeHistory=authoritative.ledger();check(nativeHistory.sessions.size()==3&&nativeHistory.resources[2].consumedQuantity==.5&&nativeHistory.sessions[0].sessionId==13,"native full history not conserved");check(nativeHistory.resources[0].consumedQuantity==2&&nativeHistory.resources[1].consumedQuantity==1&&nativeHistory.sessions[1].amount==2&&nativeHistory.sessions[2].amount==1,"prior resources/history altered");check(authoritative.snapshot().actors[0].hunger==npcBefore.actors[0].hunger,"hero food relieved NPC");check(authoritative.consume(14,210,.5),"second native finite contact");
Lifecycle life(HeroSpecies::Thistletail);life.advance({1,800});check(life.species()==HeroSpecies::Thistletail&&life.stage()==LifeStage::Juvenile,"actual bird profile");StalthosState world(42);world.setHero(1,1);world.heroDied();uint64_t next=15;auto successor=beginNextLife(world,1,{},next);Lifecycle newLife(playableSpecies("Thistletail"));needs::NeedsCore newNeeds(playableSpecies("Thistletail"));check(successor.hero==2&&newLife.species()==HeroSpecies::Thistletail&&newNeeds.species()==HeroSpecies::Thistletail,"selected life components");
std::cout<<"THISTLE_REVIEW_OK selection sensing support shared_intention direct_override finite_exact_contacts replay depletion species_components\n";
}catch(const std::exception&e){std::cerr<<e.what()<<'\n';return 1;}}


